class Solution:
    def findPrimePairs(self, n: int) -> List[List[int]]:
        # Edge case: if n < 4, no prime pairs possible
        # Because smallest prime is 2, and 2+2=4
        if n < 4:
            return []

        # Generate prime numbers up to n using Sieve of Eratosthenes
        is_prime = [True] * (n + 1)
        is_prime[0] = is_prime[1] = False

        for i in range(2, int(n**0.5) + 1):
            if is_prime[i]:
                for j in range(i * i, n + 1, i):
                    is_prime[j] = False

        result = []

        # Check all possible values of x from 2 to n//2
        # For each x, check if both x and (n-x) are prime
        for x in range(2, n // 2 + 1):
            y = n - x
            if is_prime[x] and is_prime[y]:
                result.append([x, y])

        return result

